84: static void *tryParentize(const redisReadTask *task, PyObject *obj) {
85:     PyObject *parent;
86:     if (task && task->parent) {
87:         parent = (PyObject*)task->parent->obj;
88:         switch (task->parent->type) {
89:             case REDIS_REPLY_MAP:
90:                 if (task->idx % 2 == 0) {
91:                     /* Set a temporary item to save the object as a key. */
92:                     int res = PyDict_SetItem(parent, obj, Py_None);
93:                     Py_DECREF(obj);
94: 
95:                     if (res == -1) {
96:                         return NULL;
97:                     }
98:                 } else {
99:                     /* Pop the temporary item and set proper key and value. */
100:                     PyObject *last_item = PyObject_CallMethod(parent, "popitem", NULL);
101:                     PyObject *last_key = PyTuple_GetItem(last_item, 0);
102:                     PyDict_SetItem(parent, last_key, obj);
103:                     Py_DECREF(last_item);
104:                     Py_DECREF(obj);
105:                 }
106:                 break;
107:             default:
108:                 assert(PyList_Check(parent));
109:                 PyList_SET_ITEM(parent, task->idx, obj);
110:         }
111:     }
112:     return obj;
113: }
