388: static PyObject *Reader_feed(hiredis_ReaderObject *self, PyObject *args) {
389:     Py_buffer buf;
390:     Py_ssize_t off = 0;
391:     Py_ssize_t len = -1;
392: 
393:     if (!PyArg_ParseTuple(args, "s*|nn", &buf, &off, &len)) {
394:         return NULL;
395:     }
396: 
397:     if (len == -1) {
398:       len = buf.len - off;
399:     }
400: 
401:     if (off < 0 || len < 0) {
402:       PyErr_SetString(PyExc_ValueError, "negative input");
403:       goto error;
404:     }
405: 
406:     if ((off + len) > buf.len) {
407:       PyErr_SetString(PyExc_ValueError, "input is larger than buffer size");
408:       goto error;
409:     }
410: 
411:     redisReaderFeed(self->reader, (char *)buf.buf + off, len);
412:     PyBuffer_Release(&buf);
413:     Py_RETURN_NONE;
414: 
415: error:
416:     PyBuffer_Release(&buf);
417:     return NULL;
418: }
