432:         // Checking if there is no error during the call to redisReaderGetReply
433:         // to avoid getting a SystemError.
434:         if (PyErr_Occurred() == NULL) {
435:             errstr = redisReaderGetError(self->reader);
436:             /* protocolErrorClass might be a callable. call it, then use it's type */
437:             err = createError(self->protocolErrorClass, errstr, strlen(errstr));
438:         }
439: 
440:         if (err != NULL) {
441:             obj = PyObject_Type(err);
442:             PyErr_SetString(obj, errstr);
443:             Py_DECREF(obj);
